"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";

// Navbar: generated by UIX from the design system. Same variants and sizes as the Figma component.

export interface NavbarLink {
  label: React.ReactNode;
  href?: string;
  current?: boolean;
}

const navbarVariants = cva(
  "flex w-full flex-wrap items-center h-16 px-6 gap-8 max-sm:h-auto max-sm:py-3 max-sm:gap-y-3",
  {
    variants: {
      theme: {
        light: "bg-surface border-b border-line-default text-fg-primary [&_a]:text-fg-secondary [&_a]:hover:text-fg-primary [&_a[aria-current=page]]:text-fg-primary",
        dark: "skin-quiet bg-inverse text-fg-inverse [&_a]:opacity-75 [&_a]:hover:opacity-100 [&_a[aria-current=page]]:opacity-100",
        brand: "skin-quiet bg-brand text-fg-on-brand [&_a]:opacity-75 [&_a]:hover:opacity-100 [&_a[aria-current=page]]:opacity-100",
        transparent: "skin-quiet border-b border-line-default text-fg-primary [&_a]:text-current [&_a]:opacity-70 [&_a]:hover:opacity-100 [&_a[aria-current=page]]:opacity-100",
      },
    },
    defaultVariants: {
      theme: "light",
    },
  },
);

export interface NavbarProps
  extends Omit<React.HTMLAttributes<HTMLElement>, "title">,
    VariantProps<typeof navbarVariants> {
  /** Logo and name at the start. */
  brand?: React.ReactNode;
  /** Links in the middle; the current one gets aria-current. */
  links?: NavbarLink[];
  /** Search field between the links and the actions. */
  search?: React.ReactNode;
  /** Buttons, a notifications IconButton with badgeDot, an Avatar… at the end. */
  actions?: React.ReactNode;
}

const Navbar = React.forwardRef<HTMLElement, NavbarProps>(
  ({ className, theme, brand, links, search, actions, children, ...props }, ref) => (
    <header data-slot="navbar" data-kind="surface" ref={ref} className={cn(navbarVariants({ theme }), className)} {...props}>
      {brand ? <div className="flex shrink-0 items-center gap-2 text-title-medium">{brand}</div> : null}
      <nav aria-label="Main" className="flex min-w-0 flex-1 items-center gap-6 max-sm:order-last max-sm:basis-full max-sm:overflow-x-auto max-sm:[scrollbar-width:none] max-sm:[&>a]:shrink-0 max-sm:[&>a]:whitespace-nowrap">
        {links?.map((item, index) => (
          <a key={index} href={item.href} aria-current={item.current ? "page" : void 0} className="rounded-xs text-label-medium focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus">
            {item.label}
          </a>
        ))}
        {children}
      </nav>
      {search}
      {actions ? <div className="flex shrink-0 items-center max-sm:ml-auto gap-3">{actions}</div> : null}
    </header>
  ),
);
Navbar.displayName = "Navbar";

export { Navbar, navbarVariants };
